  ];

  var grid=document.getElementById("grid"),
      noResults=document.getElementById("noResults"),
      searchInput=document.getElementById("searchInput"),
      toast=document.getElementById("toast"),
      panelNotes=document.getElementById("panelNotes"),
      panelVault=document.getElementById("panelVault"),
      secretBtn=document.getElementById("secretBtn"),
      themeBtn=document.getElementById("themeBtn");

  var vaultOpen=false, lastEsc=0, memTheme="dark";

  function esc(s){return String(s).replace(/[&<>"']/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]})}
  function showToast(m){toast.textContent=m;toast.classList.add("on");clearTimeout(showToast._t);showToast._t=setTimeout(function(){toast.classList.remove("on")},1400)}
  function fallbackCopy(url,btn){
    var ta=document.createElement("textarea");
    ta.value=url;ta.style.cssText="position:fixed;opacity:0";
    document.body.appendChild(ta);ta.select();
    try{document.execCommand("copy");showToast("copied")}catch(e){}
    document.body.removeChild(ta);
    if(btn){btn.classList.add("ok");btn.textContent="✓";setTimeout(function(){btn.classList.remove("ok");btn.textContent="📋"},1000)}
  }

  function render(){
    grid.innerHTML="";
    DATA.forEach(function(g){
      var card=document.createElement("div");
      card.className="gp";
      card.dataset.n=g.n.toLowerCase();
      card.dataset.l=g.l.join(" ").toLowerCase();
      var h="<div class='gh'><div class='ge'>"+g.e+"</div><div class='gn'>"+esc(g.n)+"</div><div class='gc'>"+g.l.length+"</div><div class='gv'>▼</div></div><div class='gb'>";
      g.l.forEach(function(u){
        h+="<a class='lk' href='"+esc(u)+"' target='_blank' rel='noopener noreferrer' data-u='"+esc(u)+"'><span class='lt'>"+esc(u.replace(/^https?:\/\//,""))+"</span><button class='lc' type='button'>📋</button></a>";
      });
      h+="</div>";
      card.innerHTML=h;
      card.querySelector(".gh").onclick=function(e){
        if(e.target.closest&&e.target.closest(".lc"))return;
        card.classList.toggle("col");
      };
      card.querySelectorAll(".lc").forEach(function(btn){
        btn.onclick=function(e){
          e.preventDefault();e.stopPropagation();
          var url=btn.closest(".lk").dataset.u;
          try{
            if(navigator.clipboard&&navigator.clipboard.writeText){
              navigator.clipboard.writeText(url).then(function(){
                btn.classList.add("ok");btn.textContent="✓";showToast("copied");
                setTimeout(function(){btn.classList.remove("ok");btn.textContent="📋"},1000);
              }).catch(function(){fallbackCopy(url,btn)});
            }else{fallbackCopy(url,btn)}
          }catch(err){fallbackCopy(url,btn)}
        };
      });
      grid.appendChild(card);
    });
  }

  function filter(q){
    q=(q||"").trim().toLowerCase();
    var vis=false;
    document.querySelectorAll(".gp").forEach(function(c){
      var m=!q||c.dataset.n.indexOf(q)!==-1||c.dataset.l.indexOf(q)!==-1;
      if(m){c.classList.remove("hide");vis=true}else{c.classList.add("hide")}
    });
    noResults.classList.toggle("on",!vis);
  }

  function switchPanel(open){
    vaultOpen=open;
    if(open){
      panelNotes.classList.remove("on");
      panelVault.classList.add("on");
      secretBtn.classList.add("on");
      render();
      if(searchInput){searchInput.value="";filter("")}
    }else{
      panelVault.classList.remove("on");
      panelNotes.classList.add("on");
      secretBtn.classList.remove("on");
    }
    window.scrollTo(0,0);
  }

  if(searchInput)searchInput.oninput=function(e){filter(e.target.value)};
  document.addEventListener("keydown",function(e){
    if(e.key==="/"&&document.activeElement!==searchInput&&searchInput){
      e.preventDefault();searchInput.focus();searchInput.select();
    }
  });

  function secretClick(e){
    if(e)e.stopPropagation();
    switchPanel(!vaultOpen);
  }
  if(secretBtn){
    secretBtn.addEventListener("touchstart",secretClick,{passive:true});
    secretBtn.addEventListener("touchend",secretClick,{passive:true});
    secretBtn.addEventListener("click",secretClick,false);
    secretBtn.onclick=secretClick;
  }

  try{memTheme=localStorage.getItem("theme")||"dark"}catch(e){}
  document.documentElement.setAttribute("data-th",memTheme);
  if(themeBtn){
    themeBtn.textContent=memTheme==="dark"?"🌙":"☀️";
    function toggle(e){
      if(e)e.stopPropagation();
      var n=document.documentElement.getAttribute("data-th")==="dark"?"light":"dark";
      memTheme=n;
      document.documentElement.setAttribute("data-th",n);
      try{localStorage.setItem("theme",n)}catch(err){}
      themeBtn.textContent=n==="dark"?"🌙":"☀️";
    }
    themeBtn.addEventListener("touchstart",toggle,{passive:true});
    themeBtn.addEventListener("click",toggle,false);
    themeBtn.onclick=toggle;
  }

  document.addEventListener("keydown",function(e){
    if(e.key==="Escape"){
      var now=Date.now();
      if(now-lastEsc<400){
        try{window.location.replace("https://classroom.google.com/")}catch(err){}
      }
      lastEsc=now;
    }
  });
})();
